// ============================================================================
// Operating Mode
// ============================================================================

#[derive(Clone, Copy, PartialEq, Eq, Default, defmt::Format)]
pub enum OperatingMode {
    #[default]
    Emulation = 0,
    Passthrough = 1,
    PassthroughRaw = 2,     // Passthrough without spoof detection
    PassthroughOffset = 3,  // Passthrough with coordinate offset (spoof detection enabled)
}

impl OperatingMode {
    fn load() -> Self {
        match MODE.load(Ordering::Acquire) {
            0 => Self::Emulation,
            1 => Self::Passthrough,
            2 => Self::PassthroughRaw,
            _ => Self::PassthroughOffset,
        }
    }

    fn store(self) {
        MODE.store(self as u8, Ordering::Release);
    }
}

// ============================================================================
// Core0 Entry Point
// ============================================================================

#[embassy_executor::main]
async fn main(spawner: Spawner) {
    let p = embassy_rp::init(Default::default());

    // Initialize coordinate conversion (LLH -> ECEF) from config
    coordinates::init();

    // Initialize LAST_GOOD with default coordinates (prevents (0,0,0) = center of Earth
    // if spoofing is detected before the first valid GNSS fix)
    LAST_GOOD_LAT.store(coordinates::lat_1e7(), Ordering::Release);
    LAST_GOOD_LON.store(coordinates::lon_1e7(), Ordering::Release);
    LAST_GOOD_ALT.store(coordinates::alt_mm(), Ordering::Release);
    LAST_GOOD_ECEF_X.store(coordinates::ecef_x_cm(), Ordering::Release);
    LAST_GOOD_ECEF_Y.store(coordinates::ecef_y_cm(), Ordering::Release);
    LAST_GOOD_ECEF_Z.store(coordinates::ecef_z_cm(), Ordering::Release);

    // ========================================================================
    // Key extraction: check flash flag (set by long-press reboot) or
    // FORCE_KEY_EXTRACT debug flag.
    // If triggered → run PIO extraction BEFORE UART init (GPIO0/GPIO5 free).
    // ========================================================================
    let (extracted_key, extraction_attempted) = {
        let mut flash_tmp = Flash::<_, Async, { config::FLASH_SIZE_BYTES }>::new(p.FLASH, p.DMA_CH0);
        let request = flash_storage::load_and_clear_extract_request(&mut flash_tmp);
        drop(flash_tmp);
        let p = unsafe { embassy_rp::Peripherals::steal() };

        let should_extract = request || FORCE_KEY_EXTRACT;
        if FORCE_KEY_EXTRACT {
            warn!("KEY EXTRACT: FORCE_KEY_EXTRACT=true (debug mode)");
        }

        if should_extract {
            info!("KEY EXTRACT: running extraction (request={}, force={})", request, FORCE_KEY_EXTRACT);
            let key = key_extract::extract(p.PIO1, p.PIN_1, p.UART1, p.PIN_5).await;
            let _p = unsafe { embassy_rp::Peripherals::steal() };
            (key, true)
        } else {
            (None, false)
        }
    };
    let p = unsafe { embassy_rp::Peripherals::steal() };

    // Read drone model from flash BEFORE LED blink (model determines blink count)
    // model 0..3 → blinks 1..4 (same as button selection clicks)
    let startup_blink_count: u8 = {
        let mut flash_tmp = Flash::<_, Async, { config::FLASH_SIZE_BYTES }>::new(p.FLASH, p.DMA_CH0);
        let model = flash_storage::load_drone_model(&mut flash_tmp).unwrap_or(2); // default Air 3S
        model + 1 // Air3=1, Mavic4Pro=2, Air3S=3, Mavic3Pro=4
    };
    let p = unsafe { embassy_rp::Peripherals::steal() };

    // ===== LED feedback: extraction result or startup blink =====
    #[cfg(not(feature = "rp2354"))]
    {
        use embassy_rp::pio::Pio;
        use embassy_rp::pio_programs::ws2812::{PioWs2812, PioWs2812Program, Grb};
        use smart_leds::RGB8;

        let mut pio0 = Pio::new(p.PIO0, Irqs);
        let program = PioWs2812Program::new(&mut pio0.common);
        let mut ws: PioWs2812<_, 0, 1, Grb> = PioWs2812::with_color_order(&mut pio0.common, pio0.sm0, p.DMA_CH1, p.PIN_25, &program);

        if extraction_attempted {
            let color = if extracted_key.is_some() {
                RGB8::new(0, 50, 0) // Green = success
            } else {
                RGB8::new(50, 0, 0) // Red = failure
            };
            for _ in 0..5 {
                ws.write(&[color]).await;
                Timer::after(Duration::from_millis(100)).await;
                ws.write(&[RGB8::new(0, 0, 0)]).await;
                Timer::after(Duration::from_millis(100)).await;
            }
        } else {
            // Startup blink: N green blinks = drone model number
            // 1=Air3, 2=Mavic4Pro, 3=Air3S(default), 4=Mavic3Pro
            // Длинная пауза после серии, чтобы отличить от режима Emulation (тоже зелёный)
            for _ in 0..startup_blink_count {
                ws.write(&[RGB8::new(0, 50, 0)]).await;
                Timer::after(Duration::from_millis(150)).await;
                ws.write(&[RGB8::new(0, 0, 0)]).await;
                Timer::after(Duration::from_millis(150)).await;
            }
            Timer::after(Duration::from_millis(800)).await;
        }
    }
    // ===== END LED feedback =====

    // Re-init peripherals (PIO0 was consumed by test) - only needed when LED test runs
    #[cfg(not(feature = "rp2354"))]
    let p = unsafe { embassy_rp::Peripherals::steal() };

    // Initialize flash for mode persistence
    let flash = Flash::<_, Async, { config::FLASH_SIZE_BYTES }>::new(p.FLASH, p.DMA_CH0);
    let flash_mutex = FLASH_CELL.init(Mutex::new(flash));

    // Load saved mode from flash + save firmware version
    {
        let mut flash = flash_mutex.lock().await;

        // Load operating mode
        if let Some(mode_byte) = flash_storage::load_mode(&mut flash) {
            let mode = match mode_byte {
                0 => OperatingMode::Emulation,
                1 => OperatingMode::Passthrough,
                2 => OperatingMode::PassthroughRaw,
                _ => OperatingMode::PassthroughOffset,
            };
            mode.store();
            info!("Loaded mode {} from flash: {:?}", mode_byte, mode);
        } else {
            // No saved mode, default to Passthrough
            info!("No saved mode, defaulting to Passthrough");
            OperatingMode::Passthrough.store();
        }

        // Load drone model from flash (if set via button)
        if let Some(model_byte) = flash_storage::load_drone_model(&mut flash) {
            DRONE_MODEL.store(model_byte, Ordering::Release);
            info!("Loaded drone model from flash: {:?}", config::DroneModel::from_u8(model_byte));
        } else {
            info!("No saved drone model, using default (Air 3S)");
        }

        // Save firmware version to flash (skips write if unchanged)
        info!("Firmware version: {}", version::FW_VERSION);
        flash_storage::save_version(&mut flash, version::FW_VERSION);

        // Load previously extracted key from flash (if any)
        if let Some(key) = flash_storage::load_key(&mut flash) {
            info!("Loaded extracted private key from flash:");
            info!("  key[0..12]:  {:02x}", &key[..12]);
            info!("  key[12..24]: {:02x}", &key[12..24]);
            unsafe { sec_sign::set_flash_key(key); }
        } else {
            info!("No extracted key in flash (using hardcoded)");
        }

        // Save freshly extracted key (from key extraction mode at boot)
        if let Some(ref key) = extracted_key {
            if flash_storage::save_key(&mut flash, key) {
                info!("Freshly extracted key saved to flash");
            } else {
                error!("FAILED to save extracted key to flash!");
            }
            unsafe { sec_sign::set_flash_key(*key); }
        }
    };

    // Initialize PIO0 for WS2812 LED (only for boards with LED)
    #[cfg(not(feature = "rp2354"))]
    let pio0 = Pio::new(p.PIO0, Irqs);
    #[cfg(not(feature = "rp2354"))]
    let dma_ch1 = p.DMA_CH1;
    #[cfg(not(feature = "rp2354"))]
    let led_pin = p.PIN_25;  // WS2812B on GPIO25

    // Mode button using Flex for E9 workaround
    // RP2350: GPIO13=PWR, GPIO14=INPUT
    // RP2354: GPIO13=PWR, GPIO14=INPUT
    #[cfg(not(feature = "rp2354"))]
    let _btn_pwr = Output::new(p.PIN_13, Level::High);
    #[cfg(not(feature = "rp2354"))]
    let btn_flex = Flex::new(p.PIN_14);

    #[cfg(feature = "rp2354")]
    let _btn_pwr = Output::new(p.PIN_13, Level::High);
    #[cfg(feature = "rp2354")]
    let btn_flex = Flex::new(p.PIN_14);

    // Simple GPIO LED for RP2354: GPIO11 (anode), GPIO12 (cathode/ground)
    #[cfg(feature = "rp2354")]
    let mut led_anode = Output::new(p.PIN_11, Level::Low);
    #[cfg(feature = "rp2354")]
    let _led_cathode = Output::new(p.PIN_12, Level::Low);

    // RP2354 LED feedback: extraction result or startup blink
    #[cfg(feature = "rp2354")]
    if extraction_attempted {
        for _ in 0..5 {
            led_anode.set_high();
            Timer::after(Duration::from_millis(100)).await;
            led_anode.set_low();
            Timer::after(Duration::from_millis(100)).await;
        }
    } else {
        // Startup blink: N blinks = drone model number
        for _ in 0..startup_blink_count {
            led_anode.set_high();
            Timer::after(Duration::from_millis(150)).await;
            led_anode.set_low();
            Timer::after(Duration::from_millis(150)).await;
        }
        Timer::after(Duration::from_millis(800)).await;
    }

    // Spawn Core1 for LED (if available) and SEC-SIGN computation
    // MON moved to Core0 to avoid yield_now() contention with ECDSA on Core1
    static EXECUTOR1: StaticCell<embassy_executor::Executor> = StaticCell::new();

    #[cfg(not(feature = "rp2354"))]
    spawn_core1(
        p.CORE1,
        unsafe { &mut *core::ptr::addr_of_mut!(CORE1_STACK) },
        move || {
            let executor1 = EXECUTOR1.init(embassy_executor::Executor::new());
            executor1.run(|spawner: embassy_executor::Spawner| {
                spawner.must_spawn(led_task(pio0, dma_ch1, led_pin));
                spawner.must_spawn(sec_sign_compute_task());
                spawner.must_spawn(sec_sign_timer_task());
            });
        },
    );

    #[cfg(feature = "rp2354")]
    spawn_core1(
        p.CORE1,
        unsafe { &mut *core::ptr::addr_of_mut!(CORE1_STACK) },
        move || {
            let executor1 = EXECUTOR1.init(embassy_executor::Executor::new());
            executor1.run(|spawner: embassy_executor::Spawner| {
                spawner.must_spawn(simple_led_task(led_anode));
                spawner.must_spawn(sec_sign_compute_task());
                spawner.must_spawn(sec_sign_timer_task());
            });
        },
    );

    // ========================================================================
    // UART0: Communication with drone/host (TX=GPIO0, RX=GPIO1)
    // ========================================================================
    static TX_BUF0: StaticCell<[u8; 2048]> = StaticCell::new();
    static RX_BUF0: StaticCell<[u8; 512]> = StaticCell::new();
    let tx_buf0 = &mut TX_BUF0.init([0; 2048])[..];
    let rx_buf0 = &mut RX_BUF0.init([0; 512])[..];

    let mut uart0_config = UartConfig::default();
    uart0_config.baudrate = DEFAULT_BAUDRATE;
    let uart0 = BufferedUart::new(
        p.UART0,
        p.PIN_0, // TX
        p.PIN_1, // RX
        Irqs,
        tx_buf0,
        rx_buf0,
        uart0_config,
    );
    let (uart0_tx, uart0_rx) = uart0.split();

    // Increase UART0 TX (GPIO0) drive strength from default 4mA to 12mA
    // Fixes signal integrity issues at 921600 baud over long wires
    rp_pac::PADS_BANK0.gpio(0).modify(|w| {
        w.set_drive(rp_pac::pads::vals::Drive::_12M_A);
        w.set_pde(true);  // Pull-down enable — stabilizes TX line for drone UART RX
        w.set_slewfast(true); // Fast slew rate for 921600 baud
    });
    info!("GPIO0 (UART0 TX): 12mA drive, pull-down, fast slew");

    // ========================================================================
    // UART1: External GNSS module input (RX=GPIO5)
    // ========================================================================
    static TX_BUF1: StaticCell<[u8; 128]> = StaticCell::new();
    static RX_BUF1: StaticCell<[u8; 4096]> = StaticCell::new();
    let tx_buf1 = &mut TX_BUF1.init([0; 128])[..];
    let rx_buf1 = &mut RX_BUF1.init([0; 4096])[..];

    let mut uart1_config = UartConfig::default();
    uart1_config.baudrate = DEFAULT_BAUDRATE;
    let uart1 = BufferedUart::new(
        p.UART1,
        p.PIN_4, // TX (not used, but required)
        p.PIN_5, // RX from external GNSS
        Irqs,
        tx_buf1,
        rx_buf1,
        uart1_config,
    );

    // Reduce FIFO threshold from 7/8 (14 bytes) to 1/4 (4 bytes)
    // This triggers interrupt 3.4x more often, reducing overrun risk
    // Embassy-rp defaults to 7/8 which is too slow for 921600 baud
    rp_pac::UART1.uartifls().write(|w| {
        w.set_rxiflsel(0b001); // 1/4 full (4 bytes) - was 0b100 (14 bytes)
        w.set_txiflsel(0b000); // TX unchanged
    });
    info!("UART1 RX FIFO threshold set to 1/4 (4 bytes)");

    let (_uart1_tx, uart1_rx) = uart1.split();

    // Initialize SEC-SIGN accumulator
    {
        let mut acc = SEC_SIGN_ACC.try_lock().unwrap();
        *acc = Some(SecSignAccumulator::new());
    }

    // ========================================================================
    // Spawn all tasks - they check MODE internally for hot-switching
    // ========================================================================
    let mode = OperatingMode::load();
    info!("Starting in {:?} mode (hot-switchable)", mode);

    // Core communication tasks (always running)
    spawner.must_spawn(uart0_tx_task(uart0_tx));
    spawner.must_spawn(uart0_rx_task(uart0_rx));
    spawner.must_spawn(uart1_rx_task(uart1_rx));
    spawner.must_spawn(gnss_processing_task()); // Separated from uart1_rx to prevent overrun

    // Emulation tasks (check MODE internally, skip work in passthrough)
    spawner.must_spawn(nav_message_task());
    spawner.must_spawn(mon_message_task());
    // sec_sign_timer_task moved to Core1 — avoids UART interrupt starvation on Core0

    // Button task for mode switching (no reboot!)
    spawner.must_spawn(button_task(btn_flex, flash_mutex));

    // Diagnostic stats task (every 10 seconds)
    spawner.must_spawn(diag_stats_task());

    info!("All tasks spawned, hot-switch enabled");

    // Core0 main loop - idle
    loop {
        Timer::after(Duration::from_secs(60)).await;
    }
}

// ============================================================================
// Core1 Tasks
// ============================================================================

/// LED control task - WS2812B on PIO (runs on Core1)
/// GPIO25 on SpotPear RP2350-Core-A
/// Green = Emulation mode, Blue = Passthrough mode
/// Blinking Red = Spoofing detected (in passthrough mode)
/// Note: Not available on RP2354 (no LED connected)
#[cfg(not(feature = "rp2354"))]
#[embassy_executor::task]
async fn led_task(
    mut pio: Pio<'static, PIO0>,
    dma: embassy_rp::Peri<'static, embassy_rp::peripherals::DMA_CH1>,
    pin: embassy_rp::Peri<'static, embassy_rp::peripherals::PIN_25>,
) {
    use embassy_rp::pio_programs::ws2812::{PioWs2812, PioWs2812Program, Grb};
    use smart_leds::RGB8;

    let program = PioWs2812Program::new(&mut pio.common);
    let mut ws: PioWs2812<_, 0, 1, Grb> = PioWs2812::with_color_order(&mut pio.common, pio.sm0, dma, pin, &program);

    // Faster tick for smooth blinking during spoof detection
    let mut ticker = Ticker::every(Duration::from_millis(100));
    let mut blink_counter: u8 = 0;

    // State machine for model selection confirmation blinks
    // Each blink = 2 ticks ON (200ms) + 2 ticks OFF (200ms) = 4 ticks
    let mut confirm_remaining: u8 = 0; // blinks left to show
    let mut confirm_tick: u8 = 0;      // tick within current blink cycle

    loop {
        blink_counter = blink_counter.wrapping_add(1);

        // Check for new model confirmation request
        let new_confirm = MODEL_CONFIRM_BLINKS.swap(0, Ordering::AcqRel);
        if new_confirm > 0 {
            confirm_remaining = new_confirm;
            confirm_tick = 0;
        }

        // Model confirmation blinks: N white blinks (200ms ON, 200ms OFF each)
        if confirm_remaining > 0 {
            let phase = confirm_tick % 4;
            let color = if phase < 2 {
                RGB8::new(50, 50, 50) // White ON
            } else {
                RGB8::new(0, 0, 0)    // OFF
            };
            confirm_tick += 1;
            if confirm_tick >= confirm_remaining * 4 {
                confirm_remaining = 0;
            }
            let _ = ws.write(&[color]).await;
            ticker.next().await;
            continue;
        }

        // Model selection mode: fast cyan blinking (100ms ON, 100ms OFF)
        if IN_MODEL_SELECTION.load(Ordering::Acquire) {
            let color = if blink_counter.is_multiple_of(2) {
                RGB8::new(0, 30, 30) // Cyan ON
            } else {
                RGB8::new(0, 0, 0)   // OFF
            };
            let _ = ws.write(&[color]).await;
            ticker.next().await;
            continue;
        }

        let mode = OperatingMode::load();
        let sats_invalid = SATELLITES_INVALID.load(Ordering::Acquire);
        let spoof_detected = SPOOF_DETECTED.load(Ordering::Acquire);

        let color = match mode {
            OperatingMode::Passthrough => {
                if spoof_detected {
                    // Fast blinking red (200ms cycle = on 100ms, off 100ms)
                    if blink_counter.is_multiple_of(2) {
                        RGB8::new(50, 0, 0)  // Red ON
                    } else {
                        RGB8::new(0, 0, 0)   // OFF
                    }
                } else {
                    // Normal passthrough: solid blue (blink every 5 ticks = 500ms)
                    if blink_counter % 5 < 3 {
                        RGB8::new(0, 0, 30)  // Blue
                    } else {
                        RGB8::new(0, 0, 0)   // Off
                    }
                }
            }
            OperatingMode::PassthroughRaw => {
                // Raw passthrough (no spoof detection): purple (blink every 5 ticks = 500ms)
                if blink_counter % 5 < 3 {
                    RGB8::new(20, 0, 30)  // Purple
                } else {
                    RGB8::new(0, 0, 0)    // Off
                }
            }
            OperatingMode::PassthroughOffset => {
                // Passthrough with coordinate offset: white (blink), red if spoofing
                if spoof_detected {
                    // Fast blinking red (same as regular Passthrough)
                    if blink_counter.is_multiple_of(2) {
                        RGB8::new(50, 0, 0)  // Red ON
                    } else {
                        RGB8::new(0, 0, 0)   // OFF
                    }
                } else {
                    // Normal: white (blink every 5 ticks = 500ms)
                    if blink_counter % 5 < 3 {
                        RGB8::new(20, 20, 20)  // White
                    } else {
                        RGB8::new(0, 0, 0)     // Off
                    }
                }
            }
            OperatingMode::Emulation => {
                // Slow blink (500ms cycle)
                if blink_counter % 5 < 3 {
                    if sats_invalid {
                        RGB8::new(30, 20, 0)  // Yellow (satellites invalid)
                    } else {
                        RGB8::new(0, 30, 0)   // Green (satellites valid)
                    }
                } else {
                    RGB8::new(0, 0, 0) // Off
                }
            }
        };

        let _ = ws.write(&[color]).await;
        ticker.next().await;
    }
}

/// Simple GPIO LED task for RP2354 (runs on Core1)
/// GPIO11 = anode (+), GPIO12 = cathode (ground, always LOW)
/// Blink code pattern: количество вспышек = номер режима
/// - Режим 1 (Emulation):        1 вспышка  (50ms ON, длинная пауза)
/// - Режим 2 (Passthrough):      2 вспышки  (50ms ON, 150ms OFF, 50ms ON, длинная пауза)
/// - Режим 3 (PassthroughRaw):   3 вспышки
/// - Режим 4 (PassthroughOffset): 4 вспышки
/// При спуфинге: быстрое непрерывное мигание (50ms ON, 50ms OFF)
#[cfg(feature = "rp2354")]
#[embassy_executor::task]
async fn simple_led_task(mut led: Output<'static>) {
    // Тик 50мс, цикл ~1.5 секунды = 30 тиков
    let mut ticker = Ticker::every(Duration::from_millis(50));
    let mut tick: u8 = 0;

    // State machine for model selection confirmation blinks
    // Each blink = 2 ticks ON (100ms) + 2 ticks OFF (100ms) = 4 ticks (200ms)
    let mut confirm_remaining: u8 = 0;
    let mut confirm_tick: u8 = 0;

    loop {
        ticker.next().await;
        tick = if tick >= 29 { 0 } else { tick + 1 };

        // Check for new model confirmation request
        let new_confirm = MODEL_CONFIRM_BLINKS.swap(0, Ordering::AcqRel);
        if new_confirm > 0 {
            confirm_remaining = new_confirm;
            confirm_tick = 0;
        }

        // Model confirmation blinks: N blinks (100ms ON, 100ms OFF each)
        if confirm_remaining > 0 {
            let phase = confirm_tick % 4;
            if phase < 2 {
                led.set_high();
            } else {
                led.set_low();
            }
            confirm_tick += 1;
            if confirm_tick >= confirm_remaining * 4 {
                confirm_remaining = 0;
            }
            continue;
        }

        // Model selection mode: very fast blinking (50ms ON, 50ms OFF = every tick)
        if IN_MODEL_SELECTION.load(Ordering::Acquire) {
            if tick.is_multiple_of(2) {
                led.set_high();
            } else {
                led.set_low();
            }
            continue;
        }

        let mode = OperatingMode::load();
        let spoof_detected = SPOOF_DETECTED.load(Ordering::Acquire);

        // При спуфинге — быстрое мигание независимо от режима
        if spoof_detected && matches!(mode, OperatingMode::Passthrough | OperatingMode::PassthroughOffset) {
            // 50ms ON, 50ms OFF (каждый тик переключаем)
            if tick.is_multiple_of(2) {
                led.set_high();
            } else {
                led.set_low();
            }
            continue;
        }

        // Количество вспышек = номер режима (1-4)
        let blink_count: u8 = match mode {
            OperatingMode::Emulation => 1,
            OperatingMode::Passthrough => 2,
            OperatingMode::PassthroughRaw => 3,
            OperatingMode::PassthroughOffset => 4,
        };

        // Паттерн: 50ms ON, 150ms OFF между вспышками
        // Каждая вспышка = 1 тик ON (50ms) + 3 тика OFF (150ms) = 4 тика (200ms)
        // Всего на N вспышек нужно N*4 тиков, остаток цикла — длинная пауза
        let blink_phase_end = blink_count * 4;
        let on = if tick < blink_phase_end {
            // Внутри фазы вспышек: ON только на первом тике каждого 4-тикового цикла
            tick.is_multiple_of(4)
        } else {
            false
        };

        if on {
            led.set_high();
        } else {
            led.set_low();
        }
    }
}

/// SEC-SIGN computation task (runs on Core1 - CPU intensive)
#[embassy_executor::task]
async fn sec_sign_compute_task() {
    info!("SEC-SIGN compute task starting on Core1");

    // Initialize RNG for micro-ecc (uses RP2040 ROSC)
    sec_sign::init_rng();

    loop {
        // Wait for request from Core0
        let request = SEC_SIGN_REQUEST.receive().await;

        info!("Computing SEC-SIGN for {} packets", request.packet_count);

        // Compute z = fold(SHA256(hash || session_id))
        let z = sec_sign::compute_z(&request.sha256_hash, &request.session_id);

        // Get private key for current drone model
        let model = DroneModel::from_u8(DRONE_MODEL.load(Ordering::Acquire));
        let private_key = get_private_key(model);

        // Sign with ECDSA SECP192R1
        let signature = Signature::sign(&z, &private_key).unwrap_or_default();

        // Send result back to Core0
        let result = SecSignResult {
            sha256_hash: request.sha256_hash,
            session_id: request.session_id,
            signature,
            packet_count: request.packet_count,
        };

        if SEC_SIGN_RESULT.try_send(result).is_err() {
            DIAG_SEC_SIGN_RES_DROPS.fetch_add(1, Ordering::Relaxed);
            warn!("SEC_SIGN_RESULT full — dropping result (TX task backlogged)");
        }
        DIAG_SEC_SIGN_COMPUTED.fetch_add(1, Ordering::Relaxed);
        info!("SEC-SIGN computation complete");
    }
}

